<div class="report-hero"><div><p class="eyebrow">Automatic reporting</p><h2>Generated report archive</h2><p>Private CSV reports created by the scheduled worker. Only authorized report users can download them.</p></div><a class="btn btn-danger" href="<?= e(url('module',['name'=>'report_schedules'])) ?>"><i class="bi bi-plus-lg me-2"></i>Manage schedules</a></div>
<section class="card-panel table-panel mt-4"><div class="table-responsive"><table class="table data-table align-middle"><thead><tr><th>Schedule</th><th>Report</th><th>Frequency</th><th>Started</th><th>Rows</th><th>Status</th><th class="text-end">File</th></tr></thead><tbody>
<?php if(!$rows): ?><tr><td colspan="7"><div class="table-empty"><i class="bi bi-file-earmark-spreadsheet"></i><strong>No generated reports yet</strong><span>Create an active schedule; the cPanel cron worker generates reports when they are due.</span></div></td></tr><?php endif; ?>
<?php foreach($rows as $row): ?><tr><td><strong><?= e($row['schedule_number']) ?></strong><small class="d-block text-muted"><?= e($row['name']) ?></small></td><td><?= e(human_status($row['report_type'])) ?></td><td><?= e(human_status($row['frequency'])) ?></td><td><?= e(date('j M Y, g:i A',strtotime((string)$row['started_at']))) ?></td><td><?= e(number_format((int)$row['row_count'])) ?></td><td><span class="badge rounded-pill text-bg-<?= e(status_class((string)$row['status'])) ?>"><?= e(human_status($row['status'])) ?></span><?php if($row['error_message']): ?><small class="d-block text-danger"><?= e($row['error_message']) ?></small><?php endif; ?></td><td class="text-end"><?php if($row['status']==='completed' && $row['file_path']): ?><a class="btn btn-sm btn-light border" href="<?= e(url('reports.scheduled.download',['id'=>$row['id']])) ?>"><i class="bi bi-download me-1"></i>Download</a><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div></section>
